final class ObjIo {
    record Polygon(int number, int line, String group, int[] v) {}
    record Error(int line, String kind) {}
    static final class Face {
        int triangle, polygon, line;
        String group;
        int[] v;
        Face(int triangle, int polygon, int line, String group, int[] v) {
            this.triangle = triangle;
            this.polygon = polygon;
            this.line = line;
            this.group = group;
            this.v = v;
        }
        Face copy() {
            return new Face(triangle, polygon, line, group, v.clone());
        }
    }
    static final class Model {
        int lines, ignored;
        List<Measure.Vec> vertices = new ArrayList<>();
        List<Polygon> polygons = new ArrayList<>();
        List<Error> errors = new ArrayList<>();
        Model() {
            vertices.add(new Measure.Vec(0, 0, 0));
        }
    }
    static boolean integer(String s) {
        return s.matches("-?[0-9]+");
    }
    static Model read() throws IOException {
        Model m = new Model();
        String group = "default";
        List<String> lines = Files.readAllLines(Path.of("input/model.obj"), StandardCharsets.US_ASCII);
        m.lines = lines.size();
        for (int i = 0; i < lines.size(); i++) {
            String text = lines.get(i);
            if (text.isEmpty() || text.startsWith("#"))
                continue;
            String[] w = text.split(" ", -1);
            String command = w[0];
            if (command.equals("v")) {
                if (w.length != 4 || !integer(w[1]) || !integer(w[2]) || !integer(w[3]))
                    m.errors.add(new Error(i + 1, "bad_vertex"));
                else
                    m.vertices.add(
                        new Measure.Vec(Long.parseLong(w[1]), Long.parseLong(w[2]), Long.parseLong(w[3])));
            } else if (command.equals("f")) {
                if (w.length < 4) {
                    m.errors.add(new Error(i + 1, "short_face"));
                    continue;
                }
                int[] v = new int[w.length - 1];
                String error = null;
                for (int j = 1; j < w.length; j++) {
                    String word = w[j].split("/", -1)[0];
                    if (!integer(word)) {
                        error = "bad_index";
                        break;
                    }
                    long number;
                    try {
                        number = Long.parseLong(word);
                    } catch (NumberFormatException ex) {
                        error = "out_of_range";
                        break;
                    }
                    if (number == 0) {
                        error = "bad_index";
                        break;
                    }
                    if (number < 0)
                        number = m.vertices.size() + number;
                    if (number < 1 || number >= m.vertices.size()) {
                        error = "out_of_range";
                        break;
                    }
                    v[j - 1] = (int)number;
                }
                if (error != null)
                    m.errors.add(new Error(i + 1, error));
                else
                    m.polygons.add(new Polygon(m.polygons.size() + 1, i + 1, group, v));
            } else if (command.equals("g"))
                group = w.length > 1 ? w[1] : "default";
            else if (Set.of("vt", "vn", "s", "o", "usemtl", "mtllib").contains(command))
                m.ignored++;
            else
                m.errors.add(new Error(i + 1, "unknown_keyword"));
        }
        return m;
    }
    static List<String> repaired(List<Measure.Vec> points, List<Face> faces) {
        List<String> result = new ArrayList<>();
        result.add("# vertices " + (points.size() - 1) + " faces " + faces.size());
        for (int i = 1; i < points.size(); i++)
            result.add("v " + points.get(i));
        String previous = "";
        for (Face f : faces) {
            if (!f.group.equals(previous)) {
                result.add("g " + f.group);
                previous = f.group;
            }
            result.add("f " + Main.numbers(f.v));
        }
        return result;
    }
}

import java.util.*;

final class Orientation {
    static boolean directed(ObjIo.Face f, int a, int b) {
        for (int i = 0; i < 3; i++)
            if (f.v[i] == a && f.v[(i + 1) % 3] == b)
                return true;
        return false;
    }
    static void flip(ObjIo.Face f) {
        int t = f.v[1];
        f.v[1] = f.v[2];
        f.v[2] = t;
    }
    static List<Topology.Edge> inconsistent(List<ObjIo.Face> f,
                                            SortedMap<Topology.Edge, List<Integer>> edges) {
        List<Topology.Edge> result = new ArrayList<>();
        for (var entry : edges.entrySet())
            if (entry.getValue().size() == 2) {
                Topology.Edge e = entry.getKey();
                if (directed(f.get(entry.getValue().get(0) - 1), e.a(), e.b()) ==
                    directed(f.get(entry.getValue().get(1) - 1), e.a(), e.b()))
                    result.add(e);
            }
        return result;
    }
    static void repair(List<ObjIo.Face> faces, SortedMap<Topology.Edge, List<Integer>> edges) {
        boolean[] visited = new boolean[faces.size() + 1];
        for (int seed = 1; seed <= faces.size(); seed++) {
            if (visited[seed])
                continue;
            visited[seed] = true;
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            queue.add(seed);
            while (!queue.isEmpty()) {
                int current = queue.remove();
                ObjIo.Face f = faces.get(current - 1);
                for (int k = 0; k < 3; k++) {
                    int a = f.v[k], b = f.v[(k + 1) % 3];
                    List<Integer> ids = edges.get(Topology.edge(a, b));
                    if (ids.size() != 2)
                        continue;
                    int other = ids.get(0) == current ? ids.get(1) : ids.get(0);
                    if (visited[other])
                        continue;
                    if (directed(faces.get(other - 1), a, b))
                        flip(faces.get(other - 1));
                    visited[other] = true;
                    queue.add(other);
                }
            }
        }
    }
    static boolean[] orientable(List<ObjIo.Face> faces, Topology.Mesh mesh) {
        List<ObjIo.Face> copied = new ArrayList<>();
        for (ObjIo.Face f : faces)
            copied.add(f.copy());
        repair(copied, mesh.edges);
        List<Topology.Edge> errors = inconsistent(copied, mesh.edges);
        boolean[] result = new boolean[mesh.components.size() + 1];
        Arrays.fill(result, true);
        for (Topology.Edge e : errors)
            result[mesh.faceComponent[mesh.edges.get(e).get(0)]] = false;
        return result;
    }
}

import java.util.*;

final class Repair {
    record Snap(int number, Measure.Vec before, Measure.Vec after) {}
    record Removed(ObjIo.Face face, String reason) {}
    static List<ObjIo.Face> split(List<ObjIo.Polygon> polygons) {
        List<ObjIo.Face> result = new ArrayList<>();
        for (ObjIo.Polygon p : polygons)
            for (int i = 1; i < p.v().length - 1; i++)
                result.add(new ObjIo.Face(result.size() + 1, p.number(), p.line(), p.group(),
                                          new int[] {p.v()[0], p.v()[i], p.v()[i + 1]}));
        return result;
    }
    static List<Measure.Vec> snap(List<Measure.Vec> vertices, int spacing, List<Snap> changes) {
        List<Measure.Vec> result = new ArrayList<>();
        result.add(vertices.get(0));
        for (int i = 1; i < vertices.size(); i++) {
            Measure.Vec p = vertices.get(i);
            Measure.Vec q = new Measure.Vec(spacing * Math.floorDiv(2 * p.x() + spacing, 2L * spacing),
                                            spacing * Math.floorDiv(2 * p.y() + spacing, 2L * spacing),
                                            spacing * Math.floorDiv(2 * p.z() + spacing, 2L * spacing));
            result.add(q);
            if (!p.equals(q))
                changes.add(new Snap(i, p, q));
        }
        return result;
    }
    static int[] representatives(List<Measure.Vec> points, boolean merge) {
        int[] result = new int[points.size()];
        Map<Measure.Vec, Integer> owner = new HashMap<>();
        for (int i = 1; i < points.size(); i++) {
            if (merge) {
                owner.putIfAbsent(points.get(i), i);
                result[i] = owner.get(points.get(i));
            } else
                result[i] = i;
        }
        return result;
    }
    static List<ObjIo.Face> clean(List<ObjIo.Face> triangles, List<Measure.Vec> points, int[] representatives,
                                  boolean zero, boolean duplicate, List<Removed> removed) {
        List<ObjIo.Face> result = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (ObjIo.Face triangle : triangles) {
            ObjIo.Face f = triangle.copy();
            for (int i = 0; i < 3; i++)
                f.v[i] = representatives[f.v[i]];
            String reason = null;
            if (f.v[0] == f.v[1] || f.v[1] == f.v[2] || f.v[2] == f.v[0])
                reason = "repeated";
            else if (zero) {
                Measure.Vec n = Measure.normal(f, points);
                if (n.x() == 0 && n.y() == 0 && n.z() == 0)
                    reason = "zero_area";
            }
            if (reason == null) {
                int[] sorted = f.v.clone();
                Arrays.sort(sorted);
                String key = Main.numbers(sorted);
                if (duplicate && seen.contains(key))
                    reason = "duplicate";
                else
                    seen.add(key);
            }
            if (reason != null)
                removed.add(new Removed(triangle, reason));
            else
                result.add(f);
        }
        return result;
    }
    static int fill(List<ObjIo.Face> faces, List<Topology.Loop> loops, int maximum, Set<Integer> permitted) {
        int count = 0;
        for (Topology.Loop loop : loops) {
            List<Integer> v = loop.vertices;
            if (!loop.kind.equals("coherent") || loop.length < 3 || loop.length > maximum ||
                new HashSet<>(v).size() != loop.length || !permitted.contains(loop.component))
                continue;
            loop.filled = true;
            for (int i = 2; i < loop.length; i++) {
                faces.add(new ObjIo.Face(0, 0, 0, "fill", new int[] {v.get(0), v.get(i), v.get(i - 1)}));
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

final class Topology {
    record Edge(int a, int b) implements Comparable<Edge> {
        @Override
        public int compareTo(Edge other) {
            int c = Integer.compare(a, other.a);
            return c != 0 ? c : Integer.compare(b, other.b);
        }
        @Override
        public String toString() {
            return a + " " + b;
        }
    }
    static Edge edge(int a, int b) {
        return new Edge(Math.min(a, b), Math.max(a, b));
    }
    static final class Component {
        int number;
        List<Integer> faces = new ArrayList<>();
        SortedSet<Integer> vertices = new TreeSet<>();
        List<Edge> edges = new ArrayList<>(), boundary = new ArrayList<>(), nonmanifold = new ArrayList<>();
        List<Integer> nonmanifoldVertices = new ArrayList<>();
    }
    static final class Mesh {
        SortedMap<Edge, List<Integer>> edges = new TreeMap<>();
        List<Component> components = new ArrayList<>();
        int[] faceComponent;
        SortedMap<Integer, List<List<Integer>>> fans = new TreeMap<>();
        List<Integer> nonmanifoldVertices = new ArrayList<>();
        SortedMap<Integer, SortedSet<Integer>> neighbors = new TreeMap<>();
    }
    static List<List<Integer>> parts(SortedSet<Integer> remaining,
                                     Map<Integer, SortedSet<Integer>> neighbors) {
        List<List<Integer>> result = new ArrayList<>();
        while (!remaining.isEmpty()) {
            int seed = remaining.first();
            remaining.remove(seed);
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            queue.add(seed);
            List<Integer> part = new ArrayList<>();
            while (!queue.isEmpty()) {
                int f = queue.remove();
                part.add(f);
                for (int n : neighbors.getOrDefault(f, new TreeSet<>()))
                    if (remaining.remove(n))
                        queue.add(n);
            }
            Collections.sort(part);
            result.add(part);
        }
        return result;
    }
    static Mesh analyze(List<ObjIo.Face> faces) {
        Mesh mesh = new Mesh();
        Map<Integer, SortedSet<Integer>> adjacency = new HashMap<>();
        SortedSet<Integer> remaining = new TreeSet<>();
        for (int i = 1; i <= faces.size(); i++) {
            remaining.add(i);
            adjacency.put(i, new TreeSet<>());
            int[] v = faces.get(i - 1).v;
            for (int k = 0; k < 3; k++)
                mesh.edges.computeIfAbsent(edge(v[k], v[(k + 1) % 3]), key -> new ArrayList<>()).add(i);
        }
        for (var entry : mesh.edges.entrySet()) {
            Edge e = entry.getKey();
            mesh.neighbors.computeIfAbsent(e.a, key -> new TreeSet<>()).add(e.b);
            mesh.neighbors.computeIfAbsent(e.b, key -> new TreeSet<>()).add(e.a);
            for (int f : entry.getValue())
                adjacency.get(f).addAll(entry.getValue());
        }
        mesh.faceComponent = new int[faces.size() + 1];
        for (List<Integer> ids : parts(remaining, adjacency)) {
            Component c = new Component();
            c.number = mesh.components.size() + 1;
            c.faces = ids;
            for (int i : ids) {
                mesh.faceComponent[i] = c.number;
                for (int v : faces.get(i - 1).v)
                    c.vertices.add(v);
            }
            for (var entry : mesh.edges.entrySet())
                if (ids.contains(entry.getValue().get(0))) {
                    c.edges.add(entry.getKey());
                    if (entry.getValue().size() == 1)
                        c.boundary.add(entry.getKey());
                    if (entry.getValue().size() >= 3)
                        c.nonmanifold.add(entry.getKey());
                }
            mesh.components.add(c);
        }
        for (int v : mesh.neighbors.keySet()) {
            Map<Integer, SortedSet<Integer>> links = new HashMap<>();
            SortedSet<Integer> incident = new TreeSet<>();
            for (int i = 1; i <= faces.size(); i++)
                for (int u : faces.get(i - 1).v)
                    if (u == v) {
                        incident.add(i);
                        links.put(i, new TreeSet<>());
                        break;
                    }
            for (var entry : mesh.edges.entrySet())
                if (entry.getKey().a == v || entry.getKey().b == v)
                    for (int f : entry.getValue())
                        links.get(f).addAll(entry.getValue());
            List<List<Integer>> fans = parts(incident, links);
            mesh.fans.put(v, fans);
            if (fans.size() >= 2)
                mesh.nonmanifoldVertices.add(v);
        }
        for (Component c : mesh.components)
            for (int v : c.vertices) {
                int count = 0;
                for (List<Integer> fan : mesh.fans.get(v))
                    if (mesh.faceComponent[fan.get(0)] == c.number)
                        count++;
                if (count >= 2)
                    c.nonmanifoldVertices.add(v);
            }
        return mesh;
    }
    static final class Loop {
        int number, component, length;
        String kind;
        boolean filled;
        List<Integer> vertices;
    }
    static List<Loop> loops(List<ObjIo.Face> faces, Mesh mesh) {
        List<Loop> result = new ArrayList<>();
        for (Component c : mesh.components) {
            SortedSet<Edge> unused = new TreeSet<>(c.boundary);
            while (!unused.isEmpty()) {
                Edge first = unused.first();
                unused.remove(first);
                List<Integer> sequence = new ArrayList<>(List.of(first.a, first.b));
                int current = first.b;
                while (current != first.a) {
                    Edge chosen = null;
                    int other = Integer.MAX_VALUE;
                    for (Edge e : unused) {
                        int n = e.a == current ? e.b : e.b == current ? e.a : Integer.MAX_VALUE;
                        if (n < other) {
                            other = n;
                            chosen = e;
                        }
                    }
                    if (chosen == null)
                        break;
                    unused.remove(chosen);
                    sequence.add(other);
                    current = other;
                }
                Loop loop = new Loop();
                loop.number = result.size() + 1;
                loop.component = c.number;
                loop.vertices = sequence;
                if (current != first.a) {
                    loop.kind = "open";
                    loop.length = sequence.size() - 1;
                } else {
                    sequence.removeLast();
                    loop.length = sequence.size();
                    int forward = 0;
                    for (int i = 0; i < loop.length; i++) {
                        int a = sequence.get(i), b = sequence.get((i + 1) % loop.length);
                        int f = mesh.edges.get(edge(a, b)).get(0);
                        if (Orientation.directed(faces.get(f - 1), a, b))
                            forward++;
                    }
                    loop.kind = forward == 0 || forward == loop.length ? "coherent" : "mixed";
                    if (forward == 0)
                        Collections.reverse(sequence.subList(1, sequence.size()));
                }
                result.add(loop);
            }
        }
        return result;
    }
}
